import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform, mix, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();
  group.name = 'FilmstripCarousel';

  const strip = new THREE.Group();
  strip.name = 'strip';
  strip.rotation.y = THREE.MathUtils.degToRad(-18);
  group.add(strip);

  const baseTex = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  baseTex.colorSpace = THREE.SRGBColorSpace;

  const CARD_W = 1.6;
  const CARD_H = 1.0;
  const PITCH = 1.85;
  const N = 5;
  const captions = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  const geom = new THREE.PlaneGeometry(CARD_W, CARD_H);
  const bevelGeom = new THREE.PlaneGeometry(CARD_W + 0.05, CARD_H + 0.05);

  const shiftUniforms = [];
  const cards = [];
  const captionMeshes = [];

  const focusUniform = uniform(0);

  for (let i = 0; i < N; i++) {
    const centerIdx = Math.floor(N / 2);
    const offset = i - centerIdx;

    const bevelMat = new THREE.MeshPhysicalNodeMaterial({
      color: new THREE.Color('#16161d'),
      roughness: 0.6,
      metalness: 0.3,
    });
    const bevelMesh = new THREE.Mesh(bevelGeom, bevelMat);
    bevelMesh.position.z = -0.01;

    const uShift = uniform(0);
    shiftUniforms.push(uShift);

    const uvNode = uv().add(vec2(uShift, float(0)));
    const mat = new THREE.MeshPhysicalNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
    });
    mat.colorNode = texture(baseTex, uvNode);
    mat.transparent = true;
    mat.opacityNode = uniform(1.0);

    const cardMesh = new THREE.Mesh(geom, mat);
    cardMesh.add(bevelMesh);

    const cardGroup = new THREE.Object3D();
    cardGroup.position.x = offset * PITCH;
    cardGroup.add(cardMesh);
    strip.add(cardGroup);

    const isFocused = offset === 0;
    const scale = isFocused ? 1.0 : 0.92;
    const opacity = isFocused ? 1.0 : Math.max(0.55, 1.0 - Math.abs(offset) * 0.15);
    cardGroup.scale.setScalar(scale);
    mat.opacityNode.value = opacity;

    if (isFocused) {
      cardGroup.rotation.y = THREE.MathUtils.degToRad(18);
    }

    cards.push({ cardGroup, mat, isFocused });

    if (isFocused) {
      const underlineMat = new THREE.MeshBasicNodeMaterial({
        color: new THREE.Color('#ff2a38'),
      });
      underlineMat.emissiveNode = undefined;
      const underlineGeom = new THREE.PlaneGeometry(1.6, 0.035);
      const underline = new THREE.Mesh(underlineGeom, underlineMat);
      underline.position.set(0, -0.6, 0.02);
      cardGroup.add(underline);

      const capMesh = ctx.fontAtlas.createText(captions[i], {
        font: 'JetBrains Mono',
        fontSize: 18,
        fontWeight: 700,
        letterSpacing: 0.08,
        color: '#e8ecf2',
      });
      capMesh.position.set(0, -0.75, 0.02);
      capMesh.scale.setScalar(0.01);
      cardGroup.add(capMesh);
      captionMeshes.push(capMesh);
    }
  }

  const headline = ctx.fontAtlas.createText('The collection', {
    font: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headline.position.set(-2.6, 1.5, 0);
  headline.scale.setScalar(0.01);
  group.add(headline);

  const body = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    font: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: '#e8ecf2',
  });
  body.position.set(-2.6, -1.5, 0);
  body.scale.setScalar(0.01);
  group.add(body);

  const light = new THREE.PointLight(0xffffff, 1.0, 10);
  light.position.set(0, 1, 3);
  group.add(light);

  // apply cinematic primitives
  const primitiveConfigs = config.cinematicPrimitives || [];
  for (const p of primitiveConfigs) {
    if (ctx.primitives[p.name]) {
      ctx.primitives[p.name](strip, p.params);
    }
  }

  let scrollTween = null;
  group.userData.handlers = {
    onScroll: (delta) => {
      const intensity = 0.5;
      strip.position.x += delta * intensity;
      shiftUniforms.forEach((u, idx) => {
        u.value = THREE.MathUtils.clamp(u.value + delta * 0.02 * (idx % 2 === 0 ? 1 : -1), -0.04, 0.04);
      });
    },
    onScrollEnd: () => {
      if (scrollTween) scrollTween.kill();
      const nearestX = Math.round(strip.position.x / PITCH) * PITCH;
      scrollTween = gsap.to(strip.position, {
        x: nearestX,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overshoot: 1.04,
      });
    },
  };

  group.userData.cleanup = () => {
    if (scrollTween) scrollTween.kill();
    geom.dispose();
    bevelGeom.dispose();
    baseTex.dispose();
    cards.forEach(({ mat }) => mat.dispose());
    group.traverse((obj) => {
      if (obj.material && obj.material.dispose) obj.material.dispose();
      if (obj.geometry && obj.geometry.dispose) obj.geometry.dispose();
    });
  };

  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  return group;
}
